theorem Module.exteriorPower_det_of_basis {R : Type u} [CommRing R] {M' M'' M : Type v}
    [AddCommGroup M'] [Module R M'] [AddCommGroup M''] [Module R M'']
    [AddCommGroup M] [Module R M] {a b : ℕ}
    (e' : Module.Basis (Fin a) R M') (e'' : Module.Basis (Fin b) R M'')
    (eM : Module.Basis (Fin (a + b)) R M) :
    Nonempty ((↥(⋀[R]^a M') ⊗[R] ↥(⋀[R]^b M'')) ≃ₗ[R] ↥(⋀[R]^(a + b) M))

theorem Module.exteriorPower_det_of_linearEquivProd {R : Type u} [CommRing R] {M' M'' M : Type v}
    [AddCommGroup M'] [Module R M'] [AddCommGroup M''] [Module R M'']
    [AddCommGroup M] [Module R M] {a b : ℕ}
    (e' : Module.Basis (Fin a) R M') (e'' : Module.Basis (Fin b) R M'')
    (eq : M ≃ₗ[R] M' × M'') :
    Nonempty ((↥(⋀[R]^a M') ⊗[R] ↥(⋀[R]^b M'')) ≃ₗ[R] ↥(⋀[R]^(a + b) M))

theorem Module.exteriorPower_subsingleton_of_basis_of_lt {R : Type u} [CommRing R] {M : Type v}
    [AddCommGroup M] [Module R M] {a n : ℕ} (b : Module.Basis (Fin a) R M) (h : a < n) :
    Subsingleton (⋀[R]^n M)

theorem exteriorPowerMul_hom_ext {P : Type w} [AddCommGroup P] [Module R P] {a b : ℕ}
    {f g : ((⋀[R]^a M) ⊗[R] (⋀[R]^b M)) →ₗ[R] P}
    (h : ∀ (v : Fin a → M) (w : Fin b → M),
      f (exteriorPower.ιMulti R a v ⊗ₜ[R] exteriorPower.ιMulti R b w) =
        g (exteriorPower.ιMulti R a v ⊗ₜ[R] exteriorPower.ιMulti R b w)) :
    f = g

theorem exteriorPower_comp_finAppend {α : Type v} {β : Type w} {m n : ℕ}
    (g : α → β) (u : Fin m → α) (v : Fin n → α) :
    g ∘ Fin.append u v = Fin.append (g ∘ u) (g ∘ v)

theorem IsBlowup.exists_iso {X B C : Scheme.{u}} {I : X.IdealSheafData}
    {b : B ⟶ X} {c : C ⟶ X} (hb : IsBlowup I b) (hc : IsBlowup I c) :
    ∃ e : B ≅ C, e.hom ≫ c = b

theorem IsBlowup.isIso_of_isInvertibleIdeal
    {X B : Scheme.{u}} {I : X.IdealSheafData} {b : B ⟶ X}
    (hb : IsBlowup I b) (hI : IsInvertibleIdeal I) : IsIso b

theorem IsDimensionCycle.pointClosureDimension_eq {X : Scheme.{u}} {d : ℕ}
    {α : AlgebraicCycle X ℤ} (hα : IsDimensionCycle X d α) (x : X) (hx : α x ≠ 0) :
    pointClosureDimension X x = (d : WithBot ℕ∞)

theorem IsIntegralCycleLift.unique {X : Scheme.{u}} {β : AlgebraicCycle X ℕ∞}
    {α γ : AlgebraicCycle X ℤ} (hα : IsIntegralCycleLift β α)
    (hγ : IsIntegralCycleLift β γ) : α = γ

theorem isDimensionCycle_of_pointClosureDimension {X : Scheme.{u}} {d : ℕ}
    {α : AlgebraicCycle X ℤ} (h : ∀ x : X, α x ≠ 0 → pointClosureDimension X x = (d : WithBot ℕ∞)) :
    IsDimensionCycle X d α

theorem _root_.AlgebraicGeometry.mem_cycleSubgroup_iff {X : Scheme.{u}} {i : ℕ}
    (c : AlgebraicCycle X ℤ) :
    c ∈ AlgebraicGeometry.cycleSubgroup X i ↔ ∀ x : X, c x ≠ 0 → Order.height x = (i : ℕ∞)

theorem pointBaseMap_finite {K : Type u} [Field K] {X : Scheme.{u}}
    (f : X ⟶ Spec (CommRingCat.of K)) [LocallyOfFiniteType f]
    (x : X) (hx : IsClosed ({x} : Set X)) : (pointBaseMap f x).hom.Finite

theorem properCycle_finiteSupport {K : Type u} [Field K] {X : Scheme.{u}}
    (f : X ⟶ Spec (CommRingCat.of K)) [IsProper f] (α : AlgebraicCycle X ℤ) :
    (Function.support α).Finite

theorem zeroCycle_residueFieldDegree_pos {K : Type u} [Field K] {X : Scheme.{u}}
    (f : X ⟶ Spec (CommRingCat.of K)) [LocallyOfFiniteType f]
    (α : DimensionCycle X 0) (x : X) (hx : α.1 x ≠ 0) : 0 < residueFieldDegree f x

@[simp]
theorem finsetSum_empty {X : Scheme.{u}} {d : ℕ} {ι : Type v}
    (α : ι → DimensionCycle X d) : finsetSum ∅ α = zero X d

theorem add {X : Scheme.{u}} {d : ℕ} {α β : AlgebraicCycle X ℤ}
    (hα : IsDimensionCycle X d α) (hβ : IsDimensionCycle X d β) :
    IsDimensionCycle X d (α + β)

theorem rawZeroCycleDegree_finsetSum {K : Type u} [Field K] {X : Scheme.{u}}
    (f : X ⟶ Spec (CommRingCat.of K)) [IsProper f] {ι : Type v}
    (s : Finset ι) (α : ι → DimensionCycle X 0) :
    rawZeroCycleDegree f (DimensionCycle.finsetSum s α) =
      ∑ i ∈ s, rawZeroCycleDegree f (α i)

theorem rawZeroCycleDegree_neg {K : Type u} [Field K] {X : Scheme.{u}}
    (f : X ⟶ Spec (CommRingCat.of K)) [IsProper f] (α : DimensionCycle X 0) :
    rawZeroCycleDegree f (DimensionCycle.neg α) = -rawZeroCycleDegree f α

theorem rawZeroCycleDegree_weightedSum {K : Type u} [Field K] {X : Scheme.{u}}
    (f : X ⟶ Spec (CommRingCat.of K)) [IsProper f] {ι : Type v}
    (s : Finset ι) (n : ι → ℤ) (α : ι → DimensionCycle X 0) :
    rawZeroCycleDegree f (DimensionCycle.weightedSum s n α) =
      ∑ i ∈ s, n i * rawZeroCycleDegree f (α i)

theorem rawZeroCycleDegree_zsmul {K : Type u} [Field K] {X : Scheme.{u}}
    (f : X ⟶ Spec (CommRingCat.of K)) [IsProper f] (n : ℤ) (α : DimensionCycle X 0) :
    rawZeroCycleDegree f (DimensionCycle.zsmul n α) = n * rawZeroCycleDegree f α

theorem residueFieldDegree_comp {k : Type u} [Field k] {X Y : Scheme.{u}}
    (p : Y ⟶ Spec (CommRingCat.of k)) (f : X ⟶ Y) (x : X) :
    residueFieldDegree (f ≫ p) x = residueFieldDegree p (f x) * f.residueDegree x

@[simp]
theorem order_eq_ord {X : Scheme.{u}} [IsIntegral X] [IsLocallyNoetherian X] {z : X}
    (hz : coheight z = 1) (e : LocalPrincipalEquation X z) : e.order hz = Scheme.ord e.function z

theorem isClosed_singleton_of_coheight_eq_one {X : Scheme.{u}}
    (hdim : topologicalKrullDim X ≤ 1) (x : X) (hx : coheight x = 1) :
    IsClosed ({x} : Set X)

theorem pointClosureDimension_eq_zero_of_coheight_eq_one {X : Scheme.{u}}
    (hdim : topologicalKrullDim X ≤ 1) (x : X) (hx : coheight x = 1) :
    pointClosureDimension X x = 0

theorem isLocallyFreeRank_pullback {X Y : SchemeOver k} {L : X.scheme.Modules} {n : ℕ}
    (hL : IsLocallyFreeRank X L n) (f : Y.scheme ⟶ X.scheme) :
    IsLocallyFreeRank Y ((Scheme.Modules.pullback f).obj L) n

theorem IsFrame.restrictIso_hom_inv_apply {M : X.Modules} {W : X.Opens} {e : Γ(M, W)}
    (hf : IsFrame M W e) (V : W.toScheme.Opens) (r : Γ(W.toScheme, V)) :
    hf.restrictIso.hom.val.app (op V) (hf.restrictIso.inv.val.app (op V) r) = r

theorem IsFrame.restrictIso_inv_hom_apply {M : X.Modules} {W : X.Opens} {e : Γ(M, W)}
    (hf : IsFrame M W e) (V : W.toScheme.Opens) (s : Γ(M.restrict W.ι, V)) :
    hf.restrictIso.inv.val.app (op V) (hf.restrictIso.hom.val.app (op V) s) = s

theorem moduleTensorPowerSection_smul {U : X.Opens}
    (a : Γ(X, U)) (s : Γ(M, U)) (q : ℕ) :
    moduleTensorPowerSection (a • s) q = a ^ q • moduleTensorPowerSection s q

theorem moduleTensorSection_add_left {U : X.Opens}
    (s s' : Γ(M, U)) (t : Γ(N, U)) :
    moduleTensorSection (s + s') t = moduleTensorSection s t + moduleTensorSection s' t

theorem moduleTensorSection_add_right {U : X.Opens}
    (s : Γ(M, U)) (t t' : Γ(N, U)) :
    moduleTensorSection s (t + t') = moduleTensorSection s t + moduleTensorSection s t'

theorem AlgebraicGeometry.Scheme.finite_coheight_one_not_mem {X : AlgebraicGeometry.Scheme.{u}}
    [AlgebraicGeometry.IsIntegral X] [AlgebraicGeometry.IsNoetherian X] (U : X.Opens) [Nonempty U] :
    {z : X | Order.coheight z = 1 ∧ z ∉ U}.Finite

theorem aeval_bijective_of_algEquiv {B : Type*} [CommRing B] [Algebra R B] (e : A ≃ₐ[R] B) {a : A}
    (h : Function.Bijective (Polynomial.aeval a : R[X] →ₐ[R] A)) :
    Function.Bijective (Polynomial.aeval (e a) : R[X] →ₐ[R] B)

theorem isFraction_add (d : ℤ) {U : Opens (ProjectiveSpectrum.top 𝒜)}
    {s t : ∀ x : U, Fiber 𝒜 x.1}
    (hs : IsFraction 𝒜 d s) (ht : IsFraction 𝒜 d t) :
    IsFraction 𝒜 d (s + t)

theorem locallyFraction_add (d : ℤ) {U : Opens (ProjectiveSpectrum.top 𝒜)}
    {s t : ∀ x : U, Fiber 𝒜 x.1}
    (hs : (locallyFraction 𝒜 d).pred s) (ht : (locallyFraction 𝒜 d).pred t) :
    (locallyFraction 𝒜 d).pred (s + t)

theorem structureFraction_mul (d : ℤ) {U : Opens (ProjectiveSpectrum.top 𝒜)}
    {r : ∀ x : U, HomogeneousLocalization.AtPrime 𝒜 x.1.asHomogeneousIdeal.toIdeal}
    {s : ∀ x : U, Fiber 𝒜 x.1}
    (hr : ProjectiveSpectrum.StructureSheaf.IsFraction r)
    (hs : IsFraction 𝒜 d s) :
    IsFraction 𝒜 d (fun x ↦ (r x).val * s x)

theorem equiv_isWeightedHomogeneous (𝒜 : S.WeightedPolynomialAtlas w) (i : 𝒜.I) {m : ℕ}
    {a : S.toAffineAlgebra.sections (𝒜.chart i)} (ha : a ∈ S.grading (𝒜.chart i) m) :
    (𝒜.equiv i a).IsWeightedHomogeneous w m

theorem symm_mem (𝒜 : S.WeightedPolynomialAtlas w) (i : 𝒜.I) {m : ℕ}
    {p : MvPolynomial σ Γ(X, (𝒜.chart i).toOpens)} (hp : p.IsWeightedHomogeneous w m) :
    (𝒜.equiv i).symm p ∈ S.grading (𝒜.chart i) m

theorem pointBaseMap_essFiniteType {k : Type u} [Field k] {X : Scheme.{u}}
    (f : X ⟶ Spec (CommRingCat.of k)) [LocallyOfFiniteType f] (x : X) :
    (pointBaseMap f x).hom.EssFiniteType

theorem pointBaseMap_finTrdeg {k : Type u} [Field k] {X : Scheme.{u}}
    (f : X ⟶ Spec (CommRingCat.of k)) [LocallyOfFiniteType f] (x : X) :
    letI : Algebra k (X.residueField x)

theorem map_mem_reesPiece {t : B} {t' : B'} (ht : χ t = t') {j : ℕ} {x : A ⊗[R] B}
    (hx : x ∈ reesPiece 𝒜 t j) :
    GradedBaseChange.map φ ψ χ hψ hχ x ∈ reesPiece 𝒜' t' j

theorem map_mem_tensorSub {M : Submodule R A} {M' : Submodule R' A'}
    (h : ∀ a ∈ M, ψ a ∈ M') {x : A ⊗[R] B} (hx : x ∈ tensorSub (B := B) M) :
    GradedBaseChange.map φ ψ χ hψ hχ x ∈ tensorSub (B := B') M'

theorem mem_reesPiece_of {e j : ℕ} {x : A ⊗[R] B}
    (hx : x ∈ tensorSub (B := B) (irrPow 𝒜 (j - e) j)) :
    lam (A := A) t ^ e * x ∈ reesPiece 𝒜 t j

theorem mul_mem_reesPiece {j k : ℕ} {x y : A ⊗[R] B}
    (hx : x ∈ reesPiece 𝒜 t j) (hy : y ∈ reesPiece 𝒜 t k) :
    x * y ∈ reesPiece 𝒜 t (j + k)

theorem tensorSub_mul {M N P : Submodule R A}
    (h : ∀ a ∈ M, ∀ b ∈ N, a * b ∈ P) {x y : A ⊗[R] B}
    (hx : x ∈ tensorSub (B := B) M) (hy : y ∈ tensorSub (B := B) N) :
    x * y ∈ tensorSub (B := B) P

theorem eq_monomial_of_mem (I : Ideal R) {n : ℕ} {f : reesAlgebra I}
    (hf : f ∈ grading I n) :
    (f : Polynomial R) = Polynomial.monomial n ((f : Polynomial R).coeff n)

theorem symmetric_lift_linearMap_mem (f : M →ₗ[R] N) {n : ℕ}
    {x : SymmetricAlgebra R M} (hx : x ∈ symmetricPiece R M n) :
    SymmetricAlgebra.lift ((SymmetricAlgebra.ι R N).comp f) x ∈ symmetricPiece R N n

theorem homog_mul (p q : R[X]) {m n : ℕ}
    (hp : p.natDegree ≤ m) (hq : q.natDegree ≤ n) :
    homog (p * q) (m + n) = homog p m * homog q n

theorem homog_of_le_degree (p : R[X]) {d r : ℕ}
    (hdegree : p.natDegree ≤ d) (hdr : d ≤ r) :
    homog p r = MvPolynomial.X 0 ^ (r - d) * homog p d

theorem ordinaryDegree_ne_zero_of_homogeneous {w : ι → ℕ} {q : ℕ}
    (p : MvPolynomial ι R) (hp : p.IsWeightedHomogeneous w q) (hq : q ≠ 0)
    (d : ι →₀ ℕ) (hd : d ∈ p.support) : ordinaryDegree d ≠ 0

theorem ordinaryScale_zero_of_homogeneous {w : ι → ℕ} {q : ℕ}
    (p : MvPolynomial ι R) (hp : p.IsWeightedHomogeneous w q) (hq : q ≠ 0) :
    ordinaryScale (0 : R) p = linearPart p

theorem polynomialScale_at_zero {w : ι → ℕ} {q : ℕ}
    (p : MvPolynomial ι R) (hp : p.IsWeightedHomogeneous w q) (hq : q ≠ 0) :
    specializeParameter 0 (polynomialScale p) = linearPart p

theorem polynomialScale_isWeightedHomogeneous {w : ι → ℕ} {q : ℕ}
    (p : MvPolynomial ι R) (hp : p.IsWeightedHomogeneous w q) :
    (polynomialScale p).IsWeightedHomogeneous w q
